import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Backdrop plane with vertical gradient
  const backdropGeo = new ctx.THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color('#0b0b10'), color('#16161d'), uv().y);
  const backdrop = new ctx.THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Main textured plane
  const planeGeo = new ctx.THREE.PlaneGeometry(2, 2);
  const planeMat = new MeshBasicNodeMaterial({ transparent: true });
  const plane = new ctx.THREE.Mesh(planeGeo, planeMat);
  plane.position.set(0, 1, 0.06);
  group.add(plane);

  // Load texture asynchronously (function stays synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // Render text content via font atlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new ctx.THREE.Group();
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'center',
    });
    txt.position.set(0, 0, 0.01);
    textGroup.add(txt);
  }
  group.add(textGroup);

  // Apply cinematic primitives if any
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name](group, prim.params);
      primitiveHandles.push(handler);
    }
  }

  // Event handlers placeholder (none defined)
  group.userData.handlers = {};

  // Cleanup routine
  group.userData.cleanup = () => {
    // Dispose geometries and materials
    backdropGeo.dispose();
    backdropMat.dispose();
    planeGeo.dispose();
    planeMat.dispose();

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h.cleanup) h.cleanup();
    }

    // Kill any GSAP timelines (none created here)
    gsap.globalTimeline.clear();
  };

  return group;
}
